import math

import torch


_TIMING_SHAPES = {
    (1, 512),
    (1, 13824),
    (64, 1024),
    (64, 8192),
    (512, 4096),
    (512, 5120),
    (2048, 4096),
    (2048, 5120),
    (4096, 512),
    (4096, 1024),
    (4096, 4096),
}


def _dtype(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])


def gen_inputs(ctx, device):
    shape = tuple(ctx["input__shape"])
    dtype = _dtype(ctx, "input")
    symmetric = bool(ctx["symmetric"])
    values = {}

    if shape == (1, 5) and not symmetric:
        i32_max = float(2147483647)
        input_tensor = torch.tensor(
            [[
                math.nextafter(i32_max, math.inf),
                i32_max + 1,
                i32_max,
                i32_max - 1,
                math.nextafter(i32_max, -math.inf),
            ]],
            dtype=dtype,
            device=device,
        )
    elif shape in _TIMING_SHAPES:
        input_tensor = torch.randn(shape, dtype=dtype, device=device) * 1000
    else:
        input_tensor = torch.rand(shape, dtype=dtype, device=device) * 1000
        if not symmetric:
            input_tensor = input_tensor - 300
    values["input"] = input_tensor

    if "scale__shape" in ctx:
        if shape == (1, 5):
            scale_value = 1.0
        elif shape in {(1, 1025), (1, 5137)}:
            scale_value = 2.1
        else:
            scale_value = 0.1
        values["scale"] = torch.tensor(
            [scale_value], dtype=torch.float32, device=device
        )

    if "azp__shape" in ctx:
        if shape == (1, 5):
            azp_value = 0
        elif shape == (1, 1025):
            azp_value = -255
        else:
            azp_value = 54
        values["azp"] = torch.tensor(
            [azp_value], dtype=torch.int32, device=device
        )

    return values


def run(input, scale, azp, symmetric):
    input_f32 = input.float()

    if scale is None:
        if symmetric:
            absmax = input_f32.abs().amax(dim=-1, keepdim=True)
            output_scale = absmax / 127.0
            inverse_scale = torch.where(
                absmax == 0,
                torch.tensor(0.0, dtype=torch.float32, device=input.device),
                127.0 / absmax,
            )
            output = (
                (input_f32 * inverse_scale)
                .round()
                .clamp(-128, 127)
                .to(torch.int8)
            )
            return output, output_scale, None

        row_max = input_f32.amax(dim=-1, keepdim=True)
        row_min = input_f32.amin(dim=-1, keepdim=True)
        output_scale = (row_max - row_min) / 255.0
        output_azp = (
            (-128.0 - row_min / output_scale)
            .round()
            .clamp(-2147483648, 2147483647)
            .to(torch.int32)
        )
        output = (
            ((input_f32 / output_scale).round() + output_azp)
            .clamp(-128, 127)
            .to(torch.int8)
        )
        return output, output_scale, output_azp

    if symmetric:
        output = (input_f32 / scale).round().clamp(-128, 127).to(torch.int8)
        return output, scale, None

    output = (
        ((input_f32 / scale).round() + azp)
        .clamp(-128, 127)
        .to(torch.int8)
    )
    return output, scale, azp


def valid(ref_outputs, sol_outputs, inputs, ctx):
    del ctx
    if len(ref_outputs) != 3 or len(sol_outputs) != 3:
        return {
            "passed": False,
            "message": "expected three outputs",
            "metrics": {},
        }

    ref_output, ref_scale, ref_azp = ref_outputs
    sol_output, sol_scale, sol_azp = sol_outputs
    input_tensor, input_scale, input_azp, symmetric = inputs
    dynamic = input_scale is None

    if not isinstance(sol_output, torch.Tensor):
        return {
            "passed": False,
            "message": "quantized output must be a tensor",
            "metrics": {},
        }
    if sol_output.shape != input_tensor.shape or sol_output.dtype is not torch.int8:
        return {
            "passed": False,
            "message": "quantized output shape or dtype mismatch",
            "metrics": {},
        }
    output_atol = 2 if dynamic and not symmetric else 1
    output_error = (
        sol_output.to(torch.int16) - ref_output.to(torch.int16)
    ).abs()
    if output_error.numel() and int(output_error.max().item()) > output_atol:
        return {
            "passed": False,
            "message": f"quantized output exceeds atol={output_atol}",
            "metrics": {},
        }

    if not isinstance(sol_scale, torch.Tensor):
        return {
            "passed": False,
            "message": "scale output must be a tensor",
            "metrics": {},
        }
    if sol_scale.shape != ref_scale.shape or sol_scale.dtype != ref_scale.dtype:
        return {
            "passed": False,
            "message": "scale output shape or dtype mismatch",
            "metrics": {},
        }
    if dynamic:
        scale_ok = torch.allclose(
            sol_scale, ref_scale, rtol=1.3e-6, atol=1e-5
        )
    else:
        scale_ok = torch.equal(sol_scale, input_scale)
    if not bool(scale_ok):
        return {
            "passed": False,
            "message": "scale output mismatch",
            "metrics": {},
        }

    if ref_azp is None:
        azp_ok = sol_azp is None
    elif not isinstance(sol_azp, torch.Tensor):
        azp_ok = False
    elif sol_azp.shape != ref_azp.shape or sol_azp.dtype != ref_azp.dtype:
        azp_ok = False
    elif dynamic:
        azp_error = (
            sol_azp.to(torch.int64) - ref_azp.to(torch.int64)
        ).abs()
        azp_ok = bool(
            not azp_error.numel() or int(azp_error.max().item()) <= 1
        )
    else:
        azp_ok = torch.equal(sol_azp, input_azp)
    if not bool(azp_ok):
        return {
            "passed": False,
            "message": "azp output mismatch",
            "metrics": {},
        }

    return {"passed": True, "message": "", "metrics": {}}
